-
-foreach ("PASSWORD", "DOMAIN", "SERVER", "CONFIGURATION", 
- "USERNAME", "NETBIOSNAME") {
- $ENV{$_} = $testenv_vars->{$_};
-}
-
 my $interfaces = join(',', ("127.0.0.6/8", 
 "127.0.0.7/8",
 "127.0.0.8/8",
@@ -443,33 +434,36 @@
 "127.0.0.10/8",
 "127.0.0.11/8"));

+my $testenv_vars = $target->setup_env("dc", "$prefix/dc", $socket_wrapper_dir);

-
 my $conffile = "$prefix/client.conf";
+my $abs_srcdir = cwd();
 open(CF, ">$conffile");
 print CF "[global]\\n";
 if (defined($ENV{VALGRIND})) {
- print CF "iconv:native = true\\n";
+ print CF "\\ticonv:native = true\\n";
 } else {
- print CF "iconv:native = false\\n";
+ print CF "\\ticonv:native = false\\n";
 }
-print CF "
+print CF 
+" netbios name = localtest
+ netbios aliases = localhost
 workgroup = $testenv_vars->{DOMAIN}
 realm = $testenv_vars->{REALM}
+ pid directory = $testenv_vars->{PIDDIR}
 ncalrpc dir = $testenv_vars->{NCALRPCDIR}
- js include = $srcdir/scripting/libjs
+ js include = $abs_srcdir/scripting/libjs
 winbindd socket directory = $testenv_vars->{WINBINDD_SOCKET_DIR}
 name resolve order = bcast
 interfaces = 127.0.0.1/8
- panic action = $srcdir/script/gdb_backtrace \\%PID\\% \\%PROG\\%
+ panic action = $abs_srcdir/script/gdb_backtrace \\%PID\\% \\%PROG\\%
 max xmit = 32K
 notify:inotify = false
 ldb:nosync = true
 system:anonymous = true
 #We don't want to pass our self-tests if the PAC code is wrong
- torture:basedir = st
+ torture:basedir = ./st
 gensec:require_pac = true
- pid directory = $testenv_vars->{PIDDIR}
 ";
 close(CF);

@@ -486,9 +480,14 @@
 $ENV{TORTURE_OPTIONS} = join(' ', @torture_options);
 print "OPTIONS $ENV{TORTURE_OPTIONS}\\n";

+foreach ("PASSWORD", "DOMAIN", "SERVER", "USERNAME", "NETBIOSNAME") {
+ $ENV{$_} = $testenv_vars->{$_};
+}
+
 my @todo = ();

 my $testsdir = "$srcdir/script/tests";
+$ENV{CONFIGURATION} = "--configfile=$conffile";

 if ($opt_quick) {
 open(IN, "$testsdir/tests_quick.sh|");
@@ -520,6 +519,8 @@

 $ENV{KRB5_CONFIG} = $testenv_vars->{KRB5_CONFIG};

+SocketWrapper::set_default_iface(6);
+
 if ($opt_testenv) {
 $ENV{PIDDIR} = $testenv_vars->{PIDDIR};
 my $term = ($ENV{TERM} or "xterm");

Subject: Re: kc & include & comment

C_Test cat ooh_include.c
 #include /* failed */
 void main(void) {}

It's a silly restriction of the C compilers that it can't handle comments
on preprocessor lines. It should at least be documented.

Subject: svn commit: samba r22145 - in branches: SAMBA_3_0/source/smbd SAMBA_3_0_25/source/smbd

Author: jra
Date: 2007-04-09 21:01:46 +0000 (Mon, 09 Apr 2007)
New Revision: 22145

WebSVN: URLTOKEN

Log:
Fix bug #4494 - reported by Kevin Jamieson .
If returning a mapped UNIX error from sendfile, don't call chain_reply.
Jeremy.

Modified:
 branches/SAMBA_3_0/source/smbd/process.c
 branches/SAMBA_3_0/source/smbd/reply.c
 branches/SAMBA_3_0_25/source/smbd/process.c
 branches/SAMBA_3_0_25/source/smbd/reply.c

Changeset:
Modified: branches/SAMBA_3_0/source/smbd/process.c
===================================================================
--- branches/SAMBA_3_0/source/smbd/process.c 2007-04-09 18:56:26 UTC (rev 22144)
+++ branches/SAMBA_3_0/source/smbd/process.c 2007-04-09 21:01:46 UTC (rev 22145)
@@ -1161,8 +1161,8 @@
 char outbuf_saved[smb_wct];
 int outsize = smb_len(outbuf) + 4;

- /* maybe its not chained */
- if (smb_com2 == 0xFF) {
+ /* Maybe its not chained, or it's an error packet. */
+ if (smb_com2 == 0xFF || SVAL(outbuf,smb_rcls) != 0) {
 SCVAL(outbuf,smb_vwv0,0xFF);
 return outsize;
 }

Modified: branches/SAMBA_3_0/source/smbd/reply.c
===================================================================
--- branches/SAMBA_3_0/source/smbd/reply.c 2007-04-09 18:56:26 UTC (rev 22144)
+++ branches/SAMBA_3_0/source/smbd/reply.c 2007-04-09 21:01:46 UTC (rev 22145)
@@ -2706,8 +2706,10 @@
 }

 nread = send_file_readX(conn, inbuf, outbuf, length, bufsize, fsp, startpos, smb_maxcnt);
- if (nread != -1)
+ /* Only call chain_reply if not an error. */
+ if (nread != -1 && SVAL(outbuf,smb_rcls) == 0) {
 nread = chain_reply(inbuf,outbuf,length,bufsize);
+ }

 END_PROFILE(SMBreadX);
 return nread;

